    let mut max_length = 0;
    let mut max_fruit = "";

    for fruit in &fruits {
        if fruit.len() > max_length {
            max_length = fruit.len();
            max_fruit = fruit;
        }
    }

    println!("The fruit with the most letters is {} and it has {} letters.", max_fruit, max_length);
}

fn main() {
    let word = "coffee";
    let mut seen = std::collections::HashSet::new();

    for c in word.chars() {
        if !seen.contains(&c) {
            println!("{}", c);
            seen.insert(c);
        }
    }
}

